import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/getting-started.md","filePath":"zh/manual/getting-started.md"}'),l={name:"zh/manual/getting-started.md"};function i(o,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>五分钟内从零到 <code>oc&gt;</code> 提示符。</p><h2 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to &quot;1. 下载&quot;">​</a></h2><p>从<a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">下载页面</a>或 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub 发布页</a>获取当前发布的 ISO：</p><ul><li><code>opencube-&lt;version&gt;.iso</code> - 支持 BIOS+UEFI 混合启动的镜像 (约 12 MiB)</li></ul><p>对照下载页面和发布说明中打印的 SHA256 值进行验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sha256sum opencube-&lt;version&gt;.iso</span></span></code></pre></div><h2 id="_2-在-qemu-中启动" tabindex="-1">2. 在 QEMU 中启动 <a class="header-anchor" href="#_2-在-qemu-中启动" aria-label="Permalink to &quot;2. 在 QEMU 中启动&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom opencube-&lt;version&gt;.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 \\</span></span>
<span class="line"><span>    -serial mon:stdio</span></span></code></pre></div><p>你将看到：</p><ol><li>GRUB 菜单：<em>Open Cube OS (slot ISO)</em> 加上强制槽位条目（A / B）- 参见 <a href="./boot-modes.html">boot-modes</a>。它会在 5 秒后自动启动。</li><li>内核启动日志：子系统每启动完成一行 <code>OK</code>（multiboot2 握手、长模式、帧缓冲、IDT、PIT、键盘、串口、PMM、VMM、堆、驱动、VFS、网络、Shell）。</li><li>横幅：<code>Open Cube OS &lt;version&gt; ready. Type &#39;help&#39; for commands.</code></li><li>提示符：<code>oc&gt; </code></li></ol><p>使用 UEFI 而非传统 BIOS：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -machine q35 \\</span></span>
<span class="line"><span>    -bios /usr/share/ovmf/OVMF.fd \\</span></span>
<span class="line"><span>    -cdrom opencube-&lt;version&gt;.iso -display none -serial mon:stdio</span></span></code></pre></div><h2 id="_3-首个命令" tabindex="-1">3. 首个命令 <a class="header-anchor" href="#_3-首个命令" aria-label="Permalink to &quot;3. 首个命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; help              (short command list)</span></span>
<span class="line"><span>oc&gt; help -a           (all 233, alphabetical)</span></span>
<span class="line"><span>oc&gt; help -w           (grouped by work package)</span></span>
<span class="line"><span>oc&gt; uname -a          (version + build + tree)</span></span>
<span class="line"><span>oc&gt; dskstat           (block devices found)</span></span>
<span class="line"><span>oc&gt; dhcp              (bring up networking)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2     (the QEMU gateway)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2     (fetch the gateway&#39;s index page)</span></span>
<span class="line"><span>oc&gt; dns example.com   (resolve a name through the QEMU DNS forwarder)</span></span>
<span class="line"><span>oc&gt; health            (CPU / memory / tasks / IO at a glance)</span></span>
<span class="line"><span>oc&gt; dmesg             (kernel ring buffer)</span></span></code></pre></div><p>包含每条命令的完整参考文档： <a href="./commands/">commands</a>。</p><h2 id="_4-键盘" tabindex="-1">4. 键盘 <a class="header-anchor" href="#_4-键盘" aria-label="Permalink to &quot;4. 键盘&quot;">​</a></h2><ul><li>Shell 行编辑器支持历史记录（上下键）、<code>Ctrl+U</code> 行删除和行内编辑。</li><li>在真实硬件上，PS/2 键盘直接驱动；通过串口（COM1）输入到 <code>-serial mon:stdio</code> 的每个按键都会进入同一个输入队列。</li><li>TUI 层（<code>tui</code> 命令）是键盘驱动的：菜单、表单和桌面启动器 - 参见 <a href="./tui-guide.html">tui-guide</a>。</li></ul><h2 id="_5-文件" tabindex="-1">5. 文件 <a class="header-anchor" href="#_5-文件" aria-label="Permalink to &quot;5. 文件&quot;">​</a></h2><p>启动系统自带一个 <code>ramfs</code>（内存文件系统）。你创建的文件在重启后会消失，除非将它们放在已挂载的卷上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                    (list devices: ata0, usda..., nvme0...)</span></span>
<span class="line"><span>oc&gt; mkfs.fat32 ata0 confirm    (optional: format a scratch disk)</span></span>
<span class="line"><span>oc&gt; fatmount ata0 /mnt         (FAT32; exfat/ext4 equivalents exist)</span></span>
<span class="line"><span>oc&gt; write /mnt/hello.txt &quot;hi&quot;  (a persistent file)</span></span>
<span class="line"><span>oc&gt; cat /mnt/hello.txt</span></span></code></pre></div><p><code>/etc</code> 卷是一个小的持久化 FAT32 镜像，系统在存在时会自动挂载 - 它包含 <code>opencube.conf</code>、SSH 主机密钥、内核日志和崩溃转储。</p><h2 id="_6-下一步去哪" tabindex="-1">6. 下一步去哪 <a class="header-anchor" href="#_6-下一步去哪" aria-label="Permalink to &quot;6. 下一步去哪&quot;">​</a></h2><ul><li><a href="./shell-basics.html">shell-basics</a> - 管道、重定向、环境变量、别名、脚本</li><li><a href="./network.html">network</a> - 完整的网络使用指南</li><li><a href="./boot-modes.html">boot-modes</a> - A/B 槽位和 GRUB 菜单功能</li><li><a href="./update-ota.html">update-ota</a> - 更新运行中的系统</li><li><a href="./recovery.html">recovery</a> - WinRE 风格的恢复工作流</li><li>从源码构建：<a href="./../dev/build.html">../dev/build.md</a></li></ul>`,24)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
